schemas.schema-01-actors.prisma:
/// User information for authentication and authorization. Stores username,
/// email, and password hash for secure login.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique username for login
  username String

  /// User email address for notifications
  email String

  /// Hashed password for secure authentication
  password_hash String

  /// Timestamp when user account was created
  created_at DateTime @db.Timestamptz

  /// Timestamp when user information was last updated
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_list_user_sessions todo_list_user_sessions[]
  todo_list_tasks todo_list_tasks[]

  @@unique([username])
}

/// Manages user sessions for authentication. Tracks session details
/// including IP, URL, and expiration time.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Foreign key referencing todo_list_users.id
  user_id String @db.Uuid

  /// IP address of the user during session creation
  ip String

  /// URL accessed during session creation
  href String

  /// Referrer URL during session creation
  referrer String

  /// Timestamp when session was created
  created_at DateTime @db.Timestamptz

  /// Timestamp when session expires
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_list_users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id, created_at])
}

schemas.schema-02-tasks.prisma:
/// Tasks created by users for their todo lists. Each task is associated with
/// a user through the user_id foreign key. Tasks have title, optional
/// description, completion status, and timestamps for creation and last
/// update.
///
/// @namespace Tasks
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_tasks {
  //----
  // COLUMNS
  //----
  /// Primary key for task identification.
  id String @id @db.Uuid

  /// Foreign key referencing the user who created the task.
  user_id String @db.Uuid

  /// Title of the task.
  title String

  /// Detailed description of the task.
  description String?

  /// Status indicating whether the task is completed.
  completed Boolean

  /// Timestamp when the task was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the task was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_list_users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id, created_at])
}

schemas.main.prisma:
generator client {
  provider        = "prisma-client-js"
  engineType      = "client"
  previewFeatures = ["postgresqlExtensions", "views"]
}
datasource db {
  provider   = "postgresql"
  url        = env("DATABASE_URL")
  extensions = [pg_trgm]
}
generator markdown {
  provider = "prisma-markdown"
  output   = "../../docs/ERD.md"
}

